BEGIN;

-- Reconcile legacy BOJ title writes using cached QOJ contest responses
-- matched by the exact problem URL and cross-checked against the reviewed BOJ bindings.
-- QOJ 10536 is Card Flipping on its problem page, matching the cached QOJ response.
-- A NULL qoj_title means both sources published the same title.
CREATE TEMP TABLE legacy_boj_title_repair (
    qoj_id bigint PRIMARY KEY,
    boj_id bigint NOT NULL,
    previous_title text NOT NULL,
    qoj_title text,
    fetched_at timestamptz NOT NULL
) ON COMMIT DROP;

