UPDATE catalog.problems p
SET payload=jsonb_set(p.payload,'{title}',to_jsonb(COALESCE(r.qoj_title,r.previous_title))),
    refresh_policy=jsonb_set(p.refresh_policy,'{fields,title}',jsonb_build_object(
        'source','qoj','url',p.payload->'link'->>'qoj','value',COALESCE(r.qoj_title,r.previous_title),
        'fetchedAt',r.fetched_at)) || '{"source":"qoj"}'::jsonb
FROM legacy_boj_title_repair r
JOIN app_private.catalog_boj_problems b ON b.boj_problem_id=r.boj_id AND b.preferred
WHERE p.id=b.catalog_problem_id AND p.is_public
    AND p.payload->'link'->>'qoj'='https://qoj.ac/problem/'||r.qoj_id
    AND p.payload->>'title'=r.previous_title
    AND p.refresh_policy#>>'{fields,title,source}'='boj'
    AND p.refresh_policy#>>'{fields,title,url}'='https://acmicpc.net/problem/'||r.boj_id
    AND p.refresh_policy#>>'{fields,title,value}'=r.previous_title
    AND NOT COALESCE(p.refresh_policy->'manual' ? 'title',false);

COMMIT;
